func answeringWriterAssertPutZeroOnError(
	tb testing.TB,
	a AnsweringWriter,
	fx AnsweringWriterFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := a.Put(ctx, fx.Value())
	if err == nil {
		tb.Skip("Put answered for a cancelled context, so this check has no error to inspect")
	}

	var zero answeringwriter.Value
	if got != zero {
		tb.Errorf("Put must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

